  ["t3", () => tools.mcp__t3_code__t3_project_create({ title: "h1", workspaceRoot: "/w/none" })],
]) { try { out.push(name + ": " + String(await call()).slice(0, 160)); } catch (e) { out.push(name + " threw: " + String(e.message).slice(0, 160)); } }
text(out.join("\n"));

